const today = new Date();
const alerts = [];

items.forEach(item => {
  const marche = item.json;
  const deadline = new Date(marche.parsed_deadline);
  const daysLeft = Math.ceil((deadline - today) / (1000*60*60*24));

  // Alerte J-7, J-3, J-1, JOUR J
  if ([7, 3, 1, 0].includes(daysLeft)) {
    let urgency = '';
    if (daysLeft === 0) urgency = '🔴 AUJOURD\'HUI - DÉPÔT OBLIGATOIRE';
    else if (daysLeft === 1) urgency = '🟠 DEMAIN - Dernier jour';
    else if (daysLeft === 3) urgency = '🟡 J-3 - Finaliser dossier';
    else urgency = '🔵 J-7 - Préparer dépôt';

    alerts.push({
      ...marche,
      daysLeft,
      urgency,
      message: `${urgency}\n\n📄 ${marche.title}\n💰 ${marche.parsed_amount?.toLocaleString()} FCFA\n👤 ${marche.company_name}\n📋 Statut: ${marche.status}\n\nAction requise: ${daysLeft <= 1 ? 'DÉPOSER MAINTENANT' : 'Vérifier complétude + signer'}`
    });
  }

  // Alerte retard dépot
  if (daysLeft < 0 && marche.status !== 'depose' && marche.status !== 'gagne' && marche.status !== 'perdu') {
    alerts.push({
      ...marche,
      daysLeft,
      urgency: '🔴 RETARD - ÉCHÉANCE DÉPASSÉE',
      message: `⚠️ ÉCHÉANCE DÉPASSÉE DE ${Math.abs(daysLeft)} JOURS\n\n📄 ${marche.title}\n👤 ${marche.company_name}\n📋 Statut: ${marche.status}\n\nAction: Marquer 'perdu' ou justifier`
    });
  }
});

return alerts.map(a => ({json: a}));

